steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { cycles(first: 50) { nodes { id name startDate endDate description } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { cycles(first: 50) { nodes { id name startsAt endsAt description } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 50, filter: { name: { contains: \"checkout timeout\" } }) { nodes { id identifier name cycle { id name } assignee { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 10) { nodes { id identifier title } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-plat-a\") { id identifier title cycle { id name startsAt endsAt } assignee { id name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { cycleUpdate(id: \"c-time\", endsAt: \"2026-10-20T00:00:00\") { success id name endsAt } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { cycleUpdate(id: \"c-time\", input: { endsAt: \"2026-10-20T00:00:00\" }) { success cycle { id name endsAt } } }"
  }'
